sp_widget.client_script:
api.controller = function($scope, $window, $sce) {
  var c = this;

  // Trust resource URL for angular iframe execution
  if (c.data.rawChatUrl) {
    c.data.chatIframeUrl = $sce.trustAsResourceUrl(c.data.rawChatUrl);
  }

  c.goBack = function() {
    var returnUrl = "?id=guest_concierge" +
      "&hotel_name=" + encodeURIComponent(c.data.hotelName || "") +
      "&city=" + encodeURIComponent(c.data.city || "") +
      "&country=" + encodeURIComponent(c.data.country || "") +
      "&room_id=" + encodeURIComponent(c.data.roomNumber || "") +
      "&guest_name=" + encodeURIComponent(c.data.guestName || "");

    $window.location.href = returnUrl;
  };
};

sp_widget.css:
/* Container Box */
.chat-container {
  max-width: 650px;
  margin: 20px auto;
  border-radius: 10px;
  box-shadow: 0 4px 15px rgba(0,0,0,0.1);
  overflow: hidden;
  border: 1px solid #e3e8ee;
}

/* Header */
.panel-heading {
  background-color: #2c3e50 !important;
  color: #ffffff !important;
  padding: 15px 20px;
  border-bottom: none;
}

.panel-heading h3 {
  margin: 0 0 5px 0;
  color: #ffffff;
  font-weight: 600;
  font-size: 18px;
}

.panel-heading p {
  margin: 0;
  opacity: 0.9;
  font-size: 13px;
  color: #cbd5e0;
}

/* Force Body to render height properly */
.chat-body {
  padding: 0 !important;
  height: 550px !important;
  min-height: 550px !important;
  background-color: #ffffff;
  position: relative;
}

/* Responsive Iframe */
.chat-iframe {
  width: 100% !important;
  height: 100% !important;
  min-height: 550px !important;
  border: none !important;
  display: block;
}

/* Mobile Screen Adjustment */
@media (max-width: 768px) {
  .chat-container {
    margin: 10px auto;
    width: 95%;
  }
  .chat-body, .chat-iframe {
    height: 480px !important;
    min-height: 480px !important;
  }
}

/* Footer */
.panel-footer {
  background-color: #f8f9fa;
  border-top: 1px solid #edf2f7;
  padding: 12px 20px;
}

.panel-footer .btn-default {
  background-color: #ffffff;
  border-color: #cbd5e0;
  color: #4a5568;
  font-weight: 500;
  border-radius: 6px;
  padding: 6px 16px;
}

sp_widget.script:
(function() {
  options.public = true;

  data.hotelName = $sp.getParameter('hotel_name') || "Grand Hyatt";
  data.city = $sp.getParameter('city') || "San Diego";
  data.country = $sp.getParameter('country') || "USA";
  data.roomNumber = $sp.getParameter('room_id') || "Room 402";
  data.guestName = $sp.getParameter('guest_name') || "Valued Guest";

  var topicSysId = "9728a04051bac3107f4405bb1590ecdc";

  // Public Virtual Agent Web Client URL with Portal context and topic binding
  data.rawChatUrl = "/$sn-va-web-client-app.do" +
    "?sysparm_topic=" + topicSysId +
    "&sysparm_portal=sp" +
    "&sysparm_anonymous=true" +
    "&sysparm_skip_load_history=true";
})();
